"""Password reset flow."""

import logging
import secrets
from datetime import UTC, datetime, timedelta

from accounts.crypto import hash_password, tokens_match

logger = logging.getLogger(__name__)

USERS: dict[str, dict] = {}
# Each account may have several outstanding tokens (e.g. the user asked for a
# reset link more than once); every entry pairs the token with when it was issued.
RESET_TOKENS: dict[str, list[tuple[str, datetime]]] = {}

# Short enough to retype from a reset email without copy and paste.
TOKEN_BYTES = 6

# A token issued longer ago than this can no longer be used to reset a password.
TOKEN_LIFETIME = timedelta(minutes=30)


def new_salt() -> str:
    """Return a per-user salt for password storage."""
    return secrets.token_hex(8)


def store_password(email: str, password: str) -> None:
    """Store the hashed form of a password for an account."""
    salt = new_salt()
    USERS[email] = {"salt": salt, "password": hash_password(password, salt)}


def make_token() -> str:
    """Return a reset token."""
    return secrets.token_urlsafe(TOKEN_BYTES)


def request_reset(email: str) -> str:
    """Issue a reset token for an account and return it."""
    token = make_token()
    RESET_TOKENS.setdefault(email, []).append((token, datetime.now(UTC)))
    logger.info("issued reset token %s... for %s", token[:4], email)
    return token


def check_token(email: str, token: str) -> bool:
    """Check a reset token against the unexpired ones issued for an account."""
    now = datetime.now(UTC)
    for issued, issued_at in RESET_TOKENS.get(email, []):
        if now - issued_at > TOKEN_LIFETIME:
            continue
        if tokens_match(issued, token):
            return True
    return False


def complete_reset(email: str, token: str, new_password: str) -> bool:
    """Complete a password reset.

    Returns False without raising if the token is unknown, already used, or
    older than TOKEN_LIFETIME. On success the new password is stored and every
    outstanding reset token for the account is cleared, so the token just used
    cannot be replayed and any other reset links sent earlier stop working too.
    """
    now = datetime.now(UTC)
    for issued, issued_at in RESET_TOKENS.get(email, []):
        if now - issued_at > TOKEN_LIFETIME:
            continue
        if tokens_match(issued, token):
            store_password(email, new_password)
            RESET_TOKENS.pop(email, None)
            return True
    return False
